	"github.com/cweill/gotests/internal/render/bindata"
	"github.com/cweill/gotests/templates"
)

type Render struct {
	tmpls *template.Template
}

func New() *Render {
	r := Render{
		tmpls: template.New("render").Funcs(map[string]interface{}{
			"Field":    fieldName,
			"Receiver": receiverName,
			"Param":    parameterName,
			"Want":     wantName,
